  await figma.setCurrentPageAsync(workspacePage);

  const frameNames = [
    "01_Check_In",
    "02_Stress_Sources",
    "03_Today",
    "04_Focus_Session",
    "05_Reflect",
    "06_Growth_Insights",
    "07_Your_Routine",
    "08_Campus_Support",
    "09_Exam_Mode",
    "10_Immediate_Support",
    "11_Your_Journey",
    "12_Micro_Exercises"
  ];

  for (let i = 0; i < frameNames.length; i++) {
    const frame = figma.createFrame();
    frame.name = frameNames[i];
